/* SPRITES DO DETETIVE (PNG embutido, fundo transparente).
   dir = 8 direções da mira: 0 leste, 1 sudeste, 2 sul (frente), 3 sudoeste, 4 oeste, 5 noroeste, 6 norte (costas), 7 nordeste. Todas com 150 px de altura.
   slide = esquivando (deslize) e dead = morrendo (nocaute), ambas viradas para a DIREITA. portrait = foto grande da tela PERSONAGENS. */
const DETSPR = (() => {
  const mk = s => { const i = new Image(); i.src = s; return i; };
  return {
    dir: [mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,'),
      mk('data:image/png;base64,')],
    slide: mk('data:image/png;base64,'), slideWH: [196, 188],
    dead: mk('data:image/png;base64,'), deadWH: [282, 164],
    portrait: mk('data:image/png;base64,')
  };
})();
